+                pane,
+                if code == KeyCode::PageDown {
+                    page
+                } else {
+                    -page
+                },
+                area,
+            );
+        }
+        (code, mods) => {
+            edit(lab, code, mods);
+            lab.follow_cursor(area);
+        }
+    }
+    false
