+            if let Some(focus) = layout.pane_at(col, row).and_then(|p| p.focus()) {
+                lab.focus = focus;
+                lab.follow_cursor(area);
+            }
+        }
+        MouseEventKind::ScrollDown => {
+            if let Some(pane) = layout.pane_at(col, row) {
+                lab.scroll_pane(pane, 3, area);
+            }
+        }
+        MouseEventKind::ScrollUp => {
+            if let Some(pane) = layout.pane_at(col, row) {
+                lab.scroll_pane(pane, -3, area);
+            }
+        }
+        _ => {}
